using System;
using System.Globalization;
namespace Lab1_Bai01
{
    // Lớp hỗ trợ nhập liệu, dùng lại để phần giải thuật dễ đọc.
    internal static class NhapLieu
    {
        public static int SoNguyen(string nhac, int min, int max)
        {
            int x;
            do { Console.Write(nhac); }
            while (!int.TryParse(Console.ReadLine(), out x) || x < min || x > max);
            return x;
        }
        public static double SoThuc(string nhac, double min, double max)
        {
            double x;
            do { Console.Write(nhac); }
            while (!double.TryParse(Console.ReadLine(), out x) || double.IsNaN(x)
                || double.IsInfinity(x) || x < min || x > max);
            return x;
        }
        public static string Chuoi(string nhac)
        {
            string s;
            do { Console.Write(nhac); s = Console.ReadLine(); }
            while (string.IsNullOrWhiteSpace(s));
            return s.Trim();
        }
        public static DateTime Ngay(string nhac)
        {
            DateTime d;
            do { Console.Write(nhac + " (dd/MM/yyyy): "); }
            while (!DateTime.TryParseExact(Console.ReadLine(), "dd/MM/yyyy",
                CultureInfo.InvariantCulture, DateTimeStyles.None, out d));
            return d.Date;
        }
        public static bool DungSai(string nhac)
        {
            bool b;
            do { Console.Write(nhac + " (true/false): "); }
            while (!bool.TryParse(Console.ReadLine(), out b));
            return b;
        }
    }
}

