namespace Lab1_Bai02
{
    internal class Program
    {
        static void Main(string[] args)
        {
            Console.InputEncoding = Encoding.UTF8;
            Console.OutputEncoding = Encoding.UTF8;
            string hoTen = NhapLieu.Chuoi("Họ tên: ");
            DateTime ngaySinh;
            do { ngaySinh = NhapLieu.Ngay("Ngày sinh"); }
            while (ngaySinh > DateTime.Today);
            Console.WriteLine("{0} | {1} tuổi", hoTen, TinhTuoi(ngaySinh, DateTime.Today));
        }
        static int TinhTuoi(DateTime ngaySinh, DateTime ngayXet)
        {
            int tuoi = ngayXet.Year - ngaySinh.Year;
            if (ngayXet < ngaySinh.AddYears(tuoi)) tuoi--;
            return tuoi;
        }
    }
}

