using System;
using System.Text;

namespace Lab1_Bai05
{
    internal class Program
    {
        static void Main(string[] args)
        {
            Console.InputEncoding = Encoding.UTF8;
            Console.OutputEncoding = Encoding.UTF8;
            int a = NhapLieu.SoNguyen("a: ", int.MinValue, int.MaxValue);
            int b = NhapLieu.SoNguyen("b: ", int.MinValue, int.MaxValue);
            string s;
            do { s = NhapLieu.Chuoi("Phép toán (+,-,*,/): "); }
            while (s.Length != 1 || "+-*/".IndexOf(s[0]) < 0);
            char c = s[0];
            if (c == '/' && b == 0)
            {
                Console.WriteLine("Không thể chia cho 0.");
                return;
            }
            double ketQua = 0;
            switch (c)
            {
                case '+': ketQua = (double)a + b; break;
                case '-': ketQua = (double)a - b; break;
                case '*': ketQua = (double)a * b; break;
                case '/': ketQua = (double)a / b; break;
            }
            Console.WriteLine("{0} {1} {2} = {3}", a, c, b, ketQua);
        }

    }
}

