using System;
using System.Text;

namespace Lab1_Bai07
{
    internal class Program
    {
        static void Main(string[] args)
        {
            Console.InputEncoding = Encoding.UTF8;
            Console.OutputEncoding = Encoding.UTF8;
            int n = NhapLieu.SoNguyen("n dương: ", 1, int.MaxValue);
            Console.WriteLine(LaArmstrong(n) ? "Là số Armstrong" : "Không là số Armstrong");
        }
        static int DemChuSo(int n)
        {
            int dem=0;
            do { dem++; n/=10; } while(n>0);
            return dem;
        }
        static long LuyThua(int a,int k)
        {
            long ketQua=1;
            for(int i=0;i<k;i++) ketQua*=a;
            return ketQua;
        }
        static bool LaArmstrong(int n)
        {
            int k=DemChuSo(n),tam=n;
            long tong=0;
            do { tong+=LuyThua(tam%10,k); tam/=10; } while(tam>0);
            return tong==n;
        }
    }
}

