using System;
using System.Text;

namespace Lab1_Bai08
{
    internal class Program
    {
        static void Main(string[] args)
        {
            Console.InputEncoding = Encoding.UTF8;
            Console.OutputEncoding = Encoding.UTF8;
            int[] a=NhapMang();
            SapXep(a);
            InMang(a);
        }
        static int[] NhapMang()
        {
            int n=NhapLieu.SoNguyen("n [3,20]: ",3,20);
            int[] a=new int[n];
            for(int i=0;i<n;i++)
                a[i]=NhapLieu.SoNguyen("a["+i+"]: ",int.MinValue,int.MaxValue);
            return a;
        }
        static void HoanDoi(ref int a,ref int b)
        {
            int tam=a;a=b;b=tam;
        }
        static void SapXep(int[] a)
        {
            for(int i=0;i<a.Length-1;i++)
                for(int j=i+1;j<a.Length;j++)
                    if(a[i]>a[j]) HoanDoi(ref a[i],ref a[j]);
        }
        static void InMang(int[] a)
        {
            foreach(int x in a) Console.Write("{0} ",x);
            Console.WriteLine();
        }
    }
}

