using System;
using System.Text;

namespace Lab1_Bai12
{
    internal class Program
    {
        static void Main(string[] args)
        {
            Console.InputEncoding = Encoding.UTF8;
            Console.OutputEncoding = Encoding.UTF8;
            int p=NhapLieu.SoNguyen("Dân số hiện tại: ",0,int.MaxValue);
            int n=NhapLieu.SoNguyen("Số năm: ",0,int.MaxValue);
            double m=NhapLieu.SoThuc("Tăng mỗi năm (%): ",0,double.MaxValue);
            double ketQua=TinhDanSo(p,m,n);
            if(double.IsNaN(ketQua) || double.IsInfinity(ketQua))
                Console.WriteLine("Kết quả vượt miền tính toán.");
            else
                Console.WriteLine("Dân số dự kiến (làm tròn để hiển thị): {0:F0}",ketQua);
        }
        static double TinhDanSo(int p,double m,int n)
        {
            if(n==0 || p==0) return p;
            return p*Math.Pow(1+m/100.0,n);
        }
    }
