        {
            if(float.IsNaN(amount) || float.IsInfinity(amount) || amount<=0)
                Console.WriteLine("Số tiền không hợp lệ.");
            else if(amount<=balance)
            {
                balance-=amount;
                Console.WriteLine("Rút thành công.");
            }
            else Console.WriteLine("Rút không được: số dư không đủ.");
        }
    }
