namespace Lab2_Bai03
{
    public class Chuoi
    {
        private string s;
        private int x,y;
        private ConsoleColor mauNen,mauChu;
        public Chuoi() : this("Sui Study Lab",0,0,ConsoleColor.DarkBlue,ConsoleColor.White) { }
        public Chuoi(string s,int x,int y,ConsoleColor nen,ConsoleColor chu)
        {
            if(string.IsNullOrEmpty(s) || s.Length>=Console.WindowWidth)
                throw new ArgumentException("Chuỗi phải ngắn hơn chiều rộng cửa sổ.");
            this.s=s;this.x=x;this.y=y;mauNen=nen;mauChu=chu;
            GioiHanViTri();
        }
        private void GioiHanViTri()
        {
            int maxX=Math.Max(0,Console.WindowWidth-s.Length-1);
            int maxY=Math.Max(0,Console.WindowHeight-1);
            x=Math.Max(0,Math.Min(x,maxX));
            y=Math.Max(0,Math.Min(y,maxY));
        }
        public void HienThi()
        {
            GioiHanViTri();
            Console.BackgroundColor=mauNen;Console.ForegroundColor=mauChu;
            Console.Clear();Console.CursorVisible=false;
            Console.SetCursorPosition(x,y);Console.Write(s);
        }
        public void ChuyenDong()
        {
            try
            {
                while(true)
                {
                    HienThi();
                    ConsoleKey phim=Console.ReadKey(true).Key;
                    if(phim==ConsoleKey.Escape) break;
                    switch(phim)
                    {
                        case ConsoleKey.LeftArrow:x--;break;
                        case ConsoleKey.RightArrow:x++;break;
                        case ConsoleKey.UpArrow:y--;break;
                        case ConsoleKey.DownArrow:y++;break;
                    }
                    GioiHanViTri();
                }
            }
            finally { Console.ResetColor();Console.CursorVisible=true;Console.Clear(); }
        }
    }
}

