namespace Lab2_Bai07
{
    public class PhepToan
    {
        private float a,b;
        private char c;
        public PhepToan(float a1=0,float b1=0,char c1='+')
        { a=a1;b=b1;c=c1; }
        public void CapNhat()
        {
            a=(float)NhapLieu.SoThuc("a: ",-float.MaxValue,float.MaxValue);
            b=(float)NhapLieu.SoThuc("b: ",-float.MaxValue,float.MaxValue);
            string s;
            do { s=NhapLieu.Chuoi("Phép toán: "); }
            while(s.Length!=1 || "+-*/".IndexOf(s[0])<0);
            c=s[0];
        }
        private float Tinhtoan()
        {
            switch(c)
            {
                case '+':return a+b;
                case '-':return a-b;
                case '*':return a*b;
                case '/':
