using System;

namespace Lab3_Bai01
{
    public class PhanSo
    {
        private long tuSo,mauSo;
        public PhanSo() : this(0,1) { }
        public PhanSo(long tu,long mau)
        {
            if(mau==0) throw new ArgumentException("Mẫu số phải khác 0.");
            if(tu==long.MinValue || mau==long.MinValue)
                throw new OverflowException("Không nhận long.MinValue để chuẩn hóa dấu an toàn.");
            tuSo=tu;mauSo=mau;RutGon();
        }
        public PhanSo(PhanSo p)
        {
            if(object.ReferenceEquals(p,null)) throw new ArgumentNullException("p");
            tuSo=p.tuSo;mauSo=p.mauSo;
        }
        private static long UCLN(long a,long b)
        {
            a=Math.Abs(a);b=Math.Abs(b);
            while(b!=0) { long r=a%b;a=b;b=r; }
            return a;
        }
        public PhanSo RutGon()
        {
            if(mauSo<0) { tuSo=-tuSo;mauSo=-mauSo; }
            long u=UCLN(tuSo,mauSo);
            tuSo/=u;mauSo/=u;
            return this;
        }
        public bool LaKhong() { return tuSo==0; }
        public void Xuat() { Console.WriteLine("{0}/{1}",tuSo,mauSo); }
        public PhanSo Cong(PhanSo p) { return this+p; }
        public PhanSo Tru(PhanSo p) { return this-p; }
        public PhanSo Nhan(PhanSo p) { return this*p; }
        public PhanSo Chia(PhanSo p) { return this/p; }
        public static PhanSo operator +(PhanSo a,PhanSo b)
        {
            checked { return new PhanSo(a.tuSo*b.mauSo+b.tuSo*a.mauSo,a.mauSo*b.mauSo); }
        }
        public static PhanSo operator -(PhanSo a,PhanSo b)
        {
            checked { return new PhanSo(a.tuSo*b.mauSo-b.tuSo*a.mauSo,a.mauSo*b.mauSo); }
        }
        public static PhanSo operator *(PhanSo a,PhanSo b)
        {
            checked { return new PhanSo(a.tuSo*b.tuSo,a.mauSo*b.mauSo); }
        }
        public static PhanSo operator /(PhanSo a,PhanSo b)
        {
            if(b.LaKhong()) throw new DivideByZeroException("Không chia cho phân số 0.");
            checked { return new PhanSo(a.tuSo*b.mauSo,a.mauSo*b.tuSo); }
        }
        public static bool operator ==(PhanSo a,PhanSo b)
        {
            if(object.ReferenceEquals(a,b)) return true;
            if(object.ReferenceEquals(a,null) || object.ReferenceEquals(b,null)) return false;
            // Mọi constructor/kết quả đã rút gọn và mẫu dương.
            return a.tuSo==b.tuSo && a.mauSo==b.mauSo;
        }
        public static bool operator !=(PhanSo a,PhanSo b) { return !(a==b); }
        public override bool Equals(object obj) { return this==(obj as PhanSo); }
        public override int GetHashCode()
        {
            unchecked { return tuSo.GetHashCode()*397 ^ mauSo.GetHashCode(); }
        }
    }
}

