            {
                if(double.IsNaN(value) || double.IsInfinity(value) || value<=0)
                    throw new ArgumentOutOfRangeException();
                giaSan=value;
            }
        }
        public PhieuLuuTru() : this("Chưa nhập","Chưa nhập",DateTime.Today,DateTime.Today,3) { }
        public PhieuLuuTru(string phong,string ten,DateTime den,DateTime di,int loai)
        {
            if(di.Date<den.Date || loai<1 || loai>3) throw new ArgumentException();
            soPhong=phong;hoTen=ten;ngayDen=den.Date;ngayDi=di.Date;loaiPhong=loai;
        }
        public void Nhap()
        {
            soPhong=NhapLieu.Chuoi("Số phòng: ");hoTen=NhapLieu.Chuoi("Khách: ");
            ngayDen=NhapLieu.Ngay("Ngày đến");
            do { ngayDi=NhapLieu.Ngay("Ngày đi không trước ngày đến"); } while(ngayDi<ngayDen);
            loaiPhong=NhapLieu.SoNguyen("Loại [1,3]: ",1,3);
        }
        public int SoNgayO() { return Math.Max(1,(ngayDi-ngayDen).Days); }
        public double GiaPhong()
        { return giaSan*(loaiPhong==1?1.5:loaiPhong==2?1.3:1.0); }
        public double TinhTien() { return SoNgayO()*GiaPhong(); }
