        {
            // Khác ngày: [ngày đến,ngày đi);cùng ngày được tính có ở ngày đó.
            DateTime dauQuy=new DateTime(2024,10,1),cuoiQuy=new DateTime(2025,1,1);
            if(ngayDen>=cuoiQuy) return false;
            if(ngayDi==ngayDen) return ngayDen>=dauQuy;
            return ngayDi>dauQuy;
        }
        public void Xuat()
        { Console.WriteLine("{0};{1};{2} ngày;giá={3:F2};tiền={4:F2}",soPhong,hoTen,SoNgayO(),GiaPhong(),TinhTien()); }
        public static bool operator <(PhieuLuuTru a,PhieuLuuTru b) { return a.SoNgayO()<b.SoNgayO(); }
        public static bool operator >(PhieuLuuTru a,PhieuLuuTru b) { return a.SoNgayO()>b.SoNgayO(); }
        public static double operator +(double tong,PhieuLuuTru p) { return tong+p.TinhTien(); }
    }
