using System;

namespace Lab3_Bai05
{
    public class Adult
    {
        private string hoTen;
        private double canNang,chieuCao;
        public Adult() : this("Chưa nhập",50,1.6) { }
        public Adult(string ten,double nang,double cao)
        {
            if(string.IsNullOrWhiteSpace(ten) || double.IsNaN(nang) || double.IsInfinity(nang)
                || double.IsNaN(cao) || double.IsInfinity(cao) || nang<=0 || cao<=0)
                throw new ArgumentException("Họ tên,khối lượng,chiều cao không hợp lệ.");
            hoTen=ten;canNang=nang;chieuCao=cao;
        }
        public Adult(Adult a)
        {
            if(a==null) throw new ArgumentNullException("a");
            hoTen=a.hoTen;canNang=a.canNang;chieuCao=a.chieuCao;
        }
        public double TinhBMI() { return canNang/(chieuCao*chieuCao); }
        public bool SucKhoeTot()
        { return canNang>=18.5*chieuCao*chieuCao && canNang<=25*chieuCao*chieuCao; }
        public string TinhTrang()
        {
            if(canNang<18.5*chieuCao*chieuCao) return "Thiếu cân";
            if(canNang<=25*chieuCao*chieuCao) return "Bình thường theo đề";
            if(canNang<30*chieuCao*chieuCao) return "Thừa cân";
            return "Béo phì theo ngưỡng đề";
        }
        public double CanDieuChinh()
        {
            if(canNang<18.5*chieuCao*chieuCao) return 18.5*chieuCao*chieuCao-canNang;
            if(canNang>25*chieuCao*chieuCao) return 25*chieuCao*chieuCao-canNang;
            return 0;
        }
        public void Xuat()
        {
            Console.ForegroundColor=SucKhoeTot()?ConsoleColor.Green:ConsoleColor.Yellow;
            Console.WriteLine("{0}; {1}kg; {2}m; BMI={3:F2}; {4}",
                hoTen,canNang,chieuCao,TinhBMI(),TinhTrang());
            Console.ResetColor();
        }
        public void XuatDieuChinh()
        {
            double doi=CanDieuChinh();
            if(doi>0) Console.WriteLine("Theo công thức bài: tăng {0:F2} kg để đạt BMI 18,5.",doi);
            else if(doi<0) Console.WriteLine("Theo công thức bài: giảm {0:F2} kg để đạt BMI 25.",-doi);
            else Console.WriteLine("Đã nằm trong khoảng BMI của bài.");
        }
    }
}

